// TestMixedStubDelegateTo pins that a wrapped implementation is called
// through, and recorded on the way past.
//
// This is what lets one generated suite run against both the double and a
// production type, which is the point of conformance testing.
func TestMixedStubDelegateTo(t *testing.T) {
	t.Parallel()

	inner := partitiontest.NewMixedStub(t)
	s := partitiontest.NewMixedStub(t, partitiontest.MixedStubDelegateTo(inner))

	t.Run("forwards Put to the wrapped implementation", func(t *testing.T) {
		var a0 context.Context
		var a1 string
		var a2 string
		var a3 string
		_ = s.Put(a0, a1, a2, a3)
		inner.OnPut.AssertCalledOnce(t, "Put must reach the wrapped implementation")
	})

	t.Run("surfaces what Put answered", func(t *testing.T) {
		// Reaching the wrapped implementation is not enough: a double that
		// called through and then discarded the answer would pass the check
		// above while telling its caller nothing true.
		want := testkit.TestError("Put-delegate")
		inner.OnPut.FaultsFor(time.Hour, want)
		var a0 context.Context
		var a1 string
		var a2 string
		var a3 string
		r0 := s.Put(a0, a1, a2, a3)
		testkit.ErrorIs(t, r0, want, "Put must surface the wrapped answer")
	})

	t.Run("forwards Read to the wrapped implementation", func(t *testing.T) {
		var a0 context.Context
		var a1 string
		var a2 string
		_, _ = s.Read(a0, a1, a2)
		inner.OnRead.AssertCalledOnce(t, "Read must reach the wrapped implementation")
	})

	t.Run("surfaces what Read answered", func(t *testing.T) {
		// Reaching the wrapped implementation is not enough: a double that
		// called through and then discarded the answer would pass the check
		// above while telling its caller nothing true.
		want := testkit.TestError("Read-delegate")
		inner.OnRead.FaultsFor(time.Hour, want)
		var a0 context.Context
		var a1 string
		var a2 string
		_, r1 := s.Read(a0, a1, a2)
		testkit.ErrorIs(t, r1, want, "Read must surface the wrapped answer")
	})
}

